<?php namespace App\Http\Controllers; use App\Models\Order; use Illuminate\Http\Request; class OrderController extends Controller { public function index(){ $u=auth()->user();$orders=Order::with(['supplier','buyer'])->when(!$u->isAdmin(),fn($q)=>$q->where('buyer_organization_id',$u->organization_id)->orWhere('supplier_organization_id',$u->organization_id))->latest()->paginate();return view('orders.index',compact('orders'));} public function show(Order $order){$u=auth()->user();abort_unless($u->isAdmin()||in_array($u->organization_id,[$order->buyer_organization_id,$order->supplier_organization_id]),403);return view('orders.show',compact('order'));} public function status(Order $order,Request $r){$u=$r->user();abort_unless($u->isAdmin()||$u->organization_id===$order->supplier_organization_id,403);$d=$r->validate(['status'=>'required|in:received,confirmed,partially_confirmed,preparing,ready,delivering,received_by_customer,cancelled']);$order->update($d);return back()->with('success','Статус обновлён.');} }
